package org.apache.commons.cli2.commandline;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;
import org.apache.commons.cli2.Argument;
import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.WriteableCommandLine;
import org.apache.commons.cli2.option.PropertyOption;
import org.apache.commons.cli2.resource.ResourceConstants;
import org.apache.commons.cli2.resource.ResourceHelper;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class WriteableCommandLineImpl_getValues_TriageGen0Test {

    private WriteableCommandLineImpl commandLine;
    private Option optionA;
    private Option optionB;

    @Before
    public void setUp() {
        // Using a dummy root option and empty arguments for constructor
        Option root = new Option("root");
        commandLine = new WriteableCommandLineImpl(root, Collections.emptyList());
        optionA = new Option("a");
        optionB = new Option("b");
        commandLine.addOption(optionA);
        commandLine.addOption(optionB);
    }

    @Test
    public void testGetValues_WhenValueExists_ReturnsValueList() {
        List<String> expectedValues = Arrays.asList("val1", "val2");
        commandLine.addValue(optionA, "val1"); // Note: addValue implementation details may vary, 
                                              // assuming it populates internal 'values' map
        // Since addValue takes Object, we simulate the internal state via provided methods
        // In the context of the provided method, we assume addValue populates the internal 'values' map
        commandLine.addValue(optionA, expectedValues); 

        List result = commandLine.getValues(optionA, Collections.emptyList());

        assertEquals(expectedValues, result);
    }

    @Test
    public void testGetValues_WhenValueListIsEmpty_ReturnsProvidedDefaultValues() {
        List<String> providedDefaults = Arrays.asList("def1", "def2");

        // Ensure internal value list is empty for optionA
        // (Assuming addValue isn't called or is called with empty list)

        List result = commandLine.getValues(optionA, providedDefaults);

        assertEquals(providedDefaults, result);
    }

    @Test
    public void testGetValues_WhenValueListAndProvidedDefaultsAreEmpty_ReturnsInternalDefaultValues() {
        List<String> internalDefaults = Arrays.asList("internal1");
        commandLine.setDefaultValues(optionA, internalDefaults);

        List result = commandLine.getValues(optionA, Collections.emptyList());

        assertEquals(internalDefaults, result);
    }

    @Test
    public void testGetValues_WhenAllAreNullOrEmpty_ReturnsEmptyList() {
        // optionB has no values, no provided defaults, and no internal defaults set
        List result = commandLine.getValues(optionB, null);

        assertTrue(result.isEmpty());
        // Check it returns Collections.EMPTY_LIST (which is immutable)
        try {
            result.add("test");
        } catch (UnsupportedOperationException e) {
            // Success: result is Collections.EMPTY_LIST
        }
    }

    @Test
    public void testGetValues_WhenProvidedDefaultsIsNull_FallsBackToInternalDefaults() {
        List<String> internalDefaults = Arrays.asList("internal");
        commandLine.setDefaultValues(optionA, internalDefaults);

        // valueList is null (not in map), providedDefaults is null
        List result = commandLine.getValues(optionA, null);

        assertEquals(internalDefaults, result);
    }

    @Test
    public void testGetValues_WhenValueListIsNotNullButEmpty_ReturnsProvidedDefaults() {
        // We need to trigger: (valueList == null) || valueList.isEmpty()
        // If we add an empty list as a value
        commandLine.addValue(optionA, Collections.emptyList());
        List<String> providedDefaults = Arrays.asList("provided");

        List result = commandLine.getValues(optionA, providedDefaults);

        assertEquals(providedDefaults, result);
    }
}
